 [('“with respect—” (interrompida) = ?',['com todo respeito (preâmbulo de discordância)','com respeito aos mortos','em respeito à lei'],0,'with respect = fórmula de discordância polida.'),('“I hear you” = ?',['entendo seu ponto','eu te ouço fisicamente','ouço você mal'],0,'I hear you = reconheço sua posição.')],
